// kp-page-title: Rank Math %page% را روی آرشیوهای صفحه‌بندی‌شده خالی رندر می‌کند؛
// این فیلتر «| صفحه N» فارسی را اضافه می‌کند (بدون تکرار اگر از قبل هست).
add_filter('rank_math/frontend/title', function ($title) {
    if (!is_paged()) {
        return $title;
    }
    $paged = get_query_var('paged') ? (int) get_query_var('paged') : 1;
    $fa = strtr((string) $paged, ['0' => '۰', '1' => '۱', '2' => '۲', '3' => '۳', '4' => '۴', '5' => '۵', '6' => '۶', '7' => '۷', '8' => '۸', '9' => '۹']);
    if (strpos($title, 'صفحه ' . $fa) !== false || strpos($title, 'Page ' . $paged) !== false) {
        return $title;
    }
    return rtrim($title) . ' | صفحه ' . $fa;
}, 99);
